{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Raltitrexed, a structurally related antifolate with a glutamate side chain and heteroaromatic core, showed only 0.6–2.0% CSF penetration in nonhuman primates, directly demonstrating that this chemotype has limited CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A glutamate-containing radiotracer with an aromatic amide/urea motif had brain uptake of only 0.34 %ID/g at 60 min in mice and was classified as a poor BBB penetrant, supporting poor CNS access for the query's ionized dicarboxylate/glutamate pharmacophore.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A moderately lipophilic aromatic amine radiotracer was excluded from rat brain and showed dramatically increased uptake after ABC-transporter inhibition, indicating efflux liability; the query's large polar zwitterionic structure is also likely transporter-limited.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ramiprilat, a dicarboxylate drug, had a free CSF/plasma ratio of about 0.02 in dogs, showing that multiply ionized carboxylate-containing compounds cross the blood-brain barrier very slowly; the query contains two carboxylates and a similar charge state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "In humans, the benzoyl-amino acid metabolite N-anisoyl-GABA reached only 0.02–0.16 µM in CSF after aniracetam treatment, attributed to poor BBB penetration; the analogous benzoyl-glutamate conjugation in the query predicts limited CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is methotrexate, a multiply ionized glutamate-containing antifolate. Transferable evidence from related antifolates, glutamate conjugates, and dicarboxylate drugs consistently shows poor brain/CSF uptake and efflux liability, and the physicochemical prior also predicts low passive permeability. Therefore meaningful CNS access after systemic administration is unlikely.",
  "evidence_gaps": [
    "No direct brain or CSF pharmacokinetic measurement for the exact query molecule is present in the supplied evidence set.",
    "The relative contribution of specific efflux transporters (P-gp, BCRP, MRPs) to the query's brain exposure is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

